#include "w2w_private.h"
#include "nvram.h"
#include "nvfs_usr.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static Boolean w2w_init_table (void) ;


/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
Boolean w2w_init_nvfs (void)
{
  return w2w_init_table() ;
}

//--------------------------------------------------------------------------//

static Boolean w2w_init_table (void)
{
  static UInt32 cur_w2w_ena_bit  = 0xFFFFFFFF;  

  switch (nvfs_rd(nvfs_w2w_ena , &cur_w2w_ena_bit))
    {
      case NVFS_OK :  
        {
          w2w_set_table(cur_w2w_ena_bit)  ;
          
          return (TRUE) ; 
        }  
    }   

  switch (nvfs_wr_create(nvfs_w2w_ena, &w2w_ena_default , sizeof(w2w_ena_default)))
    {
      case NVFS_OK :  
        {
          w2w_set_table(w2w_ena_default) ;
          
          return (TRUE) ;		//nvram_cache_commit() ;  
        }  
    }      

  return FALSE ;
}

